/**
 * Real trades the database scored itself, with the bars that followed them.
 *
 * These exist so the TypeScript scorer can be held to the SQL one. A backtest
 * is only comparable with live results if it settles trades the same way, and
 * the two implementations live in different languages with no compiler to keep
 * them honest — so the check has to be data, taken from
 * public.signal_outcomes rather than written by hand.
 *
 * Five cases per exit reason, spread across the session so they cover both
 * directions, tight and wide stops, and holds from one bar to the full ten.
 *
 * `want` is what evaluate_pending_outcomes recorded. If a change here makes
 * these fail, the scorer has drifted and every experiment run against it is
 * measuring something the live system would not agree with.
 */
export interface ScorerCase {
  tick: number;
  direction: "long" | "short";
  entry: number;
  stop: number;
  target: number;
  risk: number;
  trailTrigger: number;
  trailOffset: number;
  hold: number;
  /** [high, low, close] per bar after the signal bar. */
  fwd: [number, number, number][];
  want: { pnl: number; reason: "target" | "stop" | "trail" | "timeout"; bars: number };
}

